 document.addEventListener('DOMContentLoaded', () => {
     const form = document.getElementById('contactForm');
     const fullName = document.getElementById('fullName');
     const email = document.getElementById('email');
     const phone = document.getElementById('phone');

     const validateField = (field, regex = null) => {
         const value = field.value.trim();
         const parent = field.closest('.form-field');
         let isValid = true;

         if (field.required && !value) {
             isValid = false;
         } else if (value && regex && !regex.test(value)) {
             isValid = false;
         }

         if (isValid) {
             parent.classList.remove('error');
         } else {
             parent.classList.add('error');
         }

         return isValid;
     };

     const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
     const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;

     fullName.addEventListener('blur', () => validateField(fullName));
     email.addEventListener('blur', () => validateField(email, emailRegex));
     phone.addEventListener('blur', () => {
         if (phone.value.trim() === '') {
             phone.closest('.form-field').classList.remove('error');
         } else {
             validateField(phone, phoneRegex);
         }
     });

     form.addEventListener('submit', (e) => {
         e.preventDefault();

         const isNameValid = validateField(fullName);
         const isEmailValid = validateField(email, emailRegex);
         let isPhoneValid = true;

         if (phone.value.trim() !== '') {
             isPhoneValid = validateField(phone, phoneRegex);
         } else {
             phone.closest('.form-field').classList.remove('error');
         }

         if (isNameValid && isEmailValid && isPhoneValid) {
             alert('Form submitted successfully!');
             form.reset();
         } else {
             console.log('Form validation failed.');
